import argparse
import os
import sys
import threading
import time
from queue import Queue
from typing import Dict, List, Optional, Tuple

def parse_jobs(file_path: str) -> List[Tuple[str, str]]:
    jobs = []
    with open(file_path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split('\t')
            if len(parts) != 2:
                continue
            job_id, expr = parts
            jobs.append((job_id, expr))
    return jobs

def evaluate_expression(expr: str) -> str:
    try:
        result = eval(expr)
    except ZeroDivisionError:
        return 'error'
    except:
        return 'error'

    if isinstance(result, float) and result.is_integer():
        return str(int(result))
    else:
        return str(result)

def load_cache(cache_path: str) -> Dict[str, str]:
    if not os.path.exists(cache_path):
        return {}
    try:
        with open(cache_path, 'rb') as f:
            data = f.read()
            cache = {}
            for line in data.decode('latin-1').splitlines():
                if line:
                    parts = line.split('\t')
                    if len(parts) == 2:
                        job_id, result = parts
                        cache[job_id] = result
            return cache
    except:
        return {}

def save_cache(cache_path: str, cache_data: Dict[str, str]):
    with open(cache_path, 'wb') as f:
        for job_id, result in cache_data.items():
            f.write((job_id + '\t' + result + '\n').encode('latin-1'))

def worker(job_queue: Queue, output_queue: Queue, max_workers: int, rate: int):
    current_time = time.time()
    last_rate_time = current_time
    active_workers = 0

    while True:
        job_id, expr = job_queue.get()
        if job_id == 'STOP':
            break

        if active_workers >= max_workers:
            job_queue.put((job_id, expr))
            continue

        active_workers += 1
        try:
            result = evaluate_expression(expr)
            output_queue.put((job_id, result))
        except:
            output_queue.put((job_id, 'error'))
        finally:
            active_workers -= 1

        # Rate limiting
        current_time = time.time()
        if rate > 0:
            elapsed = current_time - last_rate_time
            if elapsed < 1.0 / rate:
                time.sleep(1.0 / rate - elapsed)
            last_rate_time = current_time

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('JOBS_FILE', help='File containing jobs')
    parser.add_argument('--max-workers', type=int, default=1, help='Maximum number of workers')
    parser.add_argument('--rate', type=int, default=0, help='Rate limit in evaluations per second')
    parser.add_argument('--cache', required=True, help='Cache file path')
    args = parser.parse_args()

    jobs = parse_jobs(args.JOBS_FILE)
    cache = load_cache(args.cache)

    output_queue = Queue()
    job_queue = Queue()

    for job_id, expr in jobs:
        if job_id in cache:
            output_queue.put((job_id, cache[job_id]))
            continue
        job_queue.put((job_id, expr))

    threads = []
    for _ in range(args.max_workers):
        t = threading.Thread(target=worker, args=(job_queue, output_queue, args.max_workers, args.rate))
        t.start()
        threads.append(t)

    for job_id, expr in jobs:
        if job_id not in cache:
            job_queue.put((job_id, expr))

    job_queue.put(('STOP', 'STOP'))

    for t in threads:
        t.join()

    # Collect results in order
    output_order = []
    seen_jobs = set()
    for _ in range(len(jobs)):
        while not output_queue.empty():
            job_id, result = output_queue.get()
            if job_id not in seen_jobs:
                output_order.append((job_id, result))
                seen_jobs.add(job_id)

    # Save cache with all results
    cache_data = {}
    for job_id, result in output_order:
        cache_data[job_id] = result
    save_cache(args.cache, cache_data)

    # Print results in order
    for job_id, result in output_order:
        print(f"{job_id}={result}")

if __name__ == '__main__':
    main()

