import argparse
import os
import sys
import threading
import time
from collections import deque
from queue import Queue
from typing import Dict, List, Optional, Tuple

def parse_expression(expr: str) -> float:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        if expr[i] == ' ' or expr[i] == '\t':
            i += 1
            continue
        if expr[i] == '(':
            tokens.append('(')
            i += 1
        elif expr[i] == ')':
            tokens.append(')')
            i += 1
        elif expr[i] in '+-*/':
            tokens.append(expr[i])
            i += 1
        else:
            num_str = ''
            while i < n and expr[i].isdigit():
                num_str += expr[i]
                i += 1
            if num_str:
                tokens.append(num_str)
    # Convert tokens to postfix notation (RPN) using Shunting-yard algorithm
    output = []
    operators = []
    for token in tokens:
        if token.isdigit():
            output.append(float(token))
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            operators.pop()  # Remove '('
        else:
            while (operators and operators[-1] != '(' and
                   ((token in '+-' and operators[-1] in '+-*/') or
                    (token in '*/' and operators[-1] in '*/'))):
                output.append(operators.pop())
            operators.append(token)
    while operators:
        output.append(operators.pop())
    # Evaluate RPN
    stack = []
    for token in output:
        if isinstance(token, float):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    return float('inf')  # Will be handled as 'error'
                stack.append(a / b)
    return stack[0] if stack else 0.0

def evaluate_job(job_id: str, expr: str, cache: Dict[str, str]) -> str:
    if job_id in cache:
        return f"{job_id}={cache[job_id]}"

    result = parse_expression(expr)
    if result == float('inf'):
        return f"{job_id}=error"
    if result.is_integer():
        return f"{job_id}={int(result)}"
    else:
        return f"{job_id}={result:.15f}".rstrip('0').rstrip('.') if '.' in f"{result:.15f}" else f"{job_id}={result:.15f}"

def load_cache(cache_path: str) -> Dict[str, str]:
    cache = {}
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            for line in f:
                if line.strip():
                    job_id, result = line.strip().split('=', 1)
                    cache[job_id] = result
    return cache

def save_cache(cache_path: str, cache: Dict[str, str]) -> None:
    with open(cache_path, 'w') as f:
        for job_id, result in sorted(cache.items()):
            f.write(f"{job_id}={result}\n")

def worker(job_queue: Queue, output_queue: Queue, max_workers: int, rate: int, cache: Dict[str, str], results: List[str], original_order: List[str]):
    while True:
